#if UNITY_EDITOR
using System.Collections.Generic;
using UnityEditor;
using UnityEngine;
using VfxKit;
using static VfxKit.VfxBuildKit;

namespace VfxEffects
{
    // Generated by vfx-shader. The prefab is rebuilt from this script: edit here, not in the Inspector.
    // Plan: Docs/VFX/EarthTusks/Plan.md
    // Earth tusks: eight stone horns (SM_VFX_Bone) erupt one after another along a straight line in front of the caster
    // (a travelling wave from near to far), standing in two staggered rows that lean inwards like a jaw, then they crumble in
    // the same order. A long dark fissure runs under the line; dust and rock sprays are kicked sideways along it as the wave passes.
    // No light at all: no glow, no flash, no ring (earth does not shine). Different from IceSpikeFan on purpose (art lead 2026-11-04):
    // mesh, layout, timing and secondary layers all differ; only the rock shader / palette are shared.
    public static class EarthTusksBuild
    {
        const string Effect = "EarthTusks";
        const string Root = "Assets/VFX/" + Effect;
        const string Shared = "Assets/VFX/IceSpike/Textures/";   // rock palette, MatCap, crack texture (shared with IceSpike)
        const string MeshDir = "Assets/VFX/_Imported/Mesh/";
        const string ShAlpha = "VFXLib/ColosoShaderAlpha_Optimized";

        const float Life = 1.9f;        // whole effect
        const float HornLife = 1.3f;    // one tusk: rise 0.13 s, stand ~0.8 s, crumble ~0.4 s
        const float Step = 0.055f;      // delay between two neighbouring tusks: the wave
        const float Z0 = 1.1f, Dz = 0.85f;   // first tusk 1.1 m in front, then every 0.85 m (about 7 m of line)

        class Horn { public float x, yaw, leanX, leanZ, xz, y; }

        // eight tusks, alternating left / right of the fissure, thicker and taller towards the far end, each with its own lean.
        // The horn mesh curves one way: yaw 0 / 3.1 flips the curve so the two rows curve towards each other like a jaw.
        static readonly Horn[] Horns =
        {
            new Horn { x = -0.65f, yaw = 3.1f, leanX = -0.25f, leanZ = -0.20f, xz = 2.0f, y = 1.6f },
            new Horn { x =  0.70f, yaw = 0.0f, leanX = -0.20f, leanZ =  0.22f, xz = 2.1f, y = 1.8f },
            new Horn { x = -0.60f, yaw = 3.4f, leanX = -0.30f, leanZ = -0.25f, xz = 2.2f, y = 2.0f },
            new Horn { x =  0.75f, yaw = -0.3f, leanX = -0.22f, leanZ =  0.25f, xz = 2.3f, y = 2.2f },
            new Horn { x = -0.70f, yaw = 3.2f, leanX = -0.34f, leanZ = -0.28f, xz = 2.4f, y = 2.4f },
            new Horn { x =  0.65f, yaw = 0.1f, leanX = -0.26f, leanZ =  0.26f, xz = 2.5f, y = 2.6f },
            new Horn { x = -0.55f, yaw = 3.0f, leanX = -0.30f, leanZ = -0.22f, xz = 2.7f, y = 2.9f },
            new Horn { x =  0.50f, yaw = 0.2f, leanX = -0.18f, leanZ =  0.15f, xz = 3.0f, y = 3.4f },   // the big one at the end
        };

        [MenuItem("VFX/" + Effect + "/Build")]
        public static void Build()
        {
            if (!ConfirmSceneSwitch()) return;
            EnsureFolders(Root, "Materials", "Prefabs", "Scenes");

            string M(string part) => Root + "/Materials/M_" + Effect + "_" + part + ".mat";
            var rockTex = Palette(Shared + "T_IceSpike_RockPalette.png");
            var matcap = ImportTexture(Shared + "T_IceSpike_MatCap.png", 256);
            var cracks = ImportTexture(Shared + "T_IceSpike_Cracks.png", 512);
            var smokeTex = ImportTexture("Assets/VFX/fx_t_smoke_02.png", 512);

            // rock: hard-banded palette + flat faces with a fake toon light + a little MatCap (VFX/FX/Rock Facet)
            var mRock = Material(M("Rock"), VfxBlend.Alpha, rockTex, "VFX/FX/Rock Facet");
            var mChunk = Material(M("Chunk"), VfxBlend.Alpha, rockTex, "VFX/FX/Rock Facet");
            mChunk.SetColor("_Tint", new Color(1.2f, 1.1f, 1f, 1f));
            foreach (var m in new[] { mRock, mChunk })
            {
                m.SetFloat("_ZWrite", 1f);
                m.SetTexture("_MatCapTex", matcap); m.SetFloat("_MatCapAmount", 0.4f);
                EditorUtility.SetDirty(m);
            }
            // fissure: dark crack lines, alpha blended (earth does not glow) + a pale dusty rim behind them
            var mCrack = Material(M("Fissure"), VfxBlend.Alpha, cracks, ShAlpha);
            Coloso(mCrack, 1f);
            mCrack.SetColor("_MainColor", new Color(0.1f, 0.06f, 0.035f, 0f));
            var mRim = Material(M("FissureRim"), VfxBlend.Alpha, cracks, ShAlpha);
            Coloso(mRim, 0.5f);
            mRim.SetColor("_MainColor", new Color(0.62f, 0.5f, 0.36f, 0f));
            // dust: default smoke texture + stock mobile shader (art lead default), tinted brown-grey by Start Color
            var mDust = Material(M("Dust"), VfxBlend.Alpha, smokeTex);

            var root = new GameObject("VFX_" + Effect);

            // ---- G1 fissure under the whole line (flat, stretched along z)
            Fissure(root.transform, "G2_FissureRim", mRim, new Vector2(2.7f, 8.6f), -4);
            Fissure(root.transform, "G1_Fissure", mCrack, new Vector2(1.9f, 7.6f), -3);

            // ---- H1 the tusks
            for (int i = 0; i < Horns.Length; i++) Tusk(root.transform, i, Horns[i], mRock);

            // ---- D1 dust and R1 rock spray along the line, emitted in step with the wave
            Sweep(root.transform, "D1_DustLine", mDust, isDust: true);
            Sweep(root.transform, "R1_RockSpray", mChunk, isDust: false);

            var prefab = SavePrefab(root, Root + "/Prefabs/VFX_" + Effect + ".prefab");
            var look = new Vector3(0f, 1.0f, 3.9f);
            const float d = 9.6f;
            var cam = look + new Vector3(0f, Mathf.Sin(60f * Mathf.Deg2Rad) * d, -Mathf.Cos(60f * Mathf.Deg2Rad) * d);
            Finish(prefab, Root, Effect, new[] { 0.05f, 0.15f, 0.3f, 0.5f, 0.8f, 1.1f, 1.4f, 1.7f }, cam, look);
        }

        public static void BuildBatch() => RunBatch(Build);

        static Texture2D Palette(string path)
        {
            ImportTexture(path, 512);
            var imp = (TextureImporter)AssetImporter.GetAtPath(path);
            imp.mipmapEnabled = false;                    // the mesh UVs live in a tiny patch: mips would smear the bands
            imp.filterMode = FilterMode.Bilinear;
            imp.alphaSource = TextureImporterAlphaSource.FromGrayScale;   // unused by the shader, only to pass the kit's alpha-blend check
            imp.SaveAndReimport();
            return AssetDatabase.LoadAssetAtPath<Texture2D>(path);
        }

        static Mesh Load(string n)
        {
            var m = AssetDatabase.LoadAssetAtPath<Mesh>(MeshDir + n + ".fbx");
            if (m == null) throw new System.InvalidOperationException("Mesh missing: " + n);
            return m;
        }

        // Coloso Alpha material for a white-on-black texture: R is the alpha, _MainColor the colour
        static void Coloso(Material m, float opacity)
        {
            m.SetFloat("_OpacityStrength", opacity);
            m.SetFloat("_TextureIntensity", 1f); m.SetFloat("_OpacityPower", 1f);
            m.SetColor("_MainColor", new Color(1f, 1f, 1f, 0f));
            m.SetFloat("_FD", 0f); m.SetFloat("_CDF", 0f); m.SetFloat("_CDFOffset", 0f); m.SetFloat("_CameraOffset", 0f);
            m.SetFloat("_CullMode", 0f); m.SetFloat("_ZwriteMode", 0f);
            m.SetFloat("_MainClampX", 1f); m.SetFloat("_MainClampY", 1f);
            m.SetFloat("_MainRIsAlpha", 1f);
            m.SetFloat("_UseMainUVCustom1ZW", 0f); m.SetFloat("_MainUVSwitch", 0f);
            m.SetFloat("_UseManual_DebugDissolve", 1f); m.SetFloat("_ManualDissolve", 1f);
            m.SetFloat("_SmoothDissolve", 1f); m.SetFloat("_MainTexRDissolve", 0f);
            EditorUtility.SetDirty(m);
        }

        // one stone tusk: a single particle at its own place, delay and lean; rises with an overshoot, stands, crumbles
        static void Tusk(Transform parent, int i, Horn h, Material mat)
        {
            var ps = Particle(parent, "H" + (i + 1), mat, lifetime: HornLife, size: 1f, color: Color.white);
            ps.transform.localPosition = new Vector3(h.x, -0.1f, Z0 + i * Dz);   // base sunk a little
            var main = ps.main;
            main.duration = Life;
            main.startSize3D = true;
            main.startSizeX = h.xz; main.startSizeZ = h.xz; main.startSizeY = h.y;
            main.startRotation3D = true;
            main.startRotationX = h.leanX; main.startRotationY = h.yaw; main.startRotationZ = h.leanZ;
            main.startColor = Color.white;
            ps.emission.SetBursts(new[] { new ParticleSystem.Burst(i * Step, (short)1) });
            var sol = ps.sizeOverLifetime;
            sol.enabled = true; sol.separateAxes = true;
            sol.x = new ParticleSystem.MinMaxCurve(1f, AnimCurve(0f, 1f, 0.7f, 1f, 1f, 0.3f));
            sol.z = new ParticleSystem.MinMaxCurve(1f, AnimCurve(0f, 1f, 0.7f, 1f, 1f, 0.3f));
            sol.y = new ParticleSystem.MinMaxCurve(1f, AnimCurve(0f, 0f, 0.1f, 1.12f, 0.16f, 1f, 0.7f, 1f, 1f, 0f));
            AlphaOverLifetime(ps, 0f, 1f, 0.9f, 1f, 1f, 0f);
            var r = ps.GetComponent<ParticleSystemRenderer>();
            r.renderMode = ParticleSystemRenderMode.Mesh;
            r.alignment = ParticleSystemRenderSpace.World;
            r.mesh = Load("SM_VFX_Bone");
            r.sortingOrder = 0;
            r.enableGPUInstancing = false;
        }

        // long dark crack on the ground, one particle stretched along z (Local alignment, object turned X 90)
        static void Fissure(Transform parent, string name, Material mat, Vector2 size, int order)
        {
            var ps = Particle(parent, name, mat, lifetime: Life, size: 1f, color: Color.white);
            ps.transform.localPosition = new Vector3(0f, 0.02f, Z0 + (Horns.Length - 1) * Dz * 0.5f);
            ps.transform.localRotation = Quaternion.Euler(90f, 0f, 0f);
            var main = ps.main;
            main.startSize3D = true; main.startSizeX = size.x; main.startSizeY = size.y; main.startSizeZ = 1f;
            var r = ps.GetComponent<ParticleSystemRenderer>();
            r.alignment = ParticleSystemRenderSpace.Local;
            r.sortingOrder = order;
            AlphaOverLifetime(ps, 0f, 0f, 0.1f, 1f, 0.7f, 0.85f, 1f, 0f);
        }

        // Particles emitted at random places along the line, in bursts spread over the time the wave needs.
        static void Sweep(Transform parent, string name, Material mat, bool isDust)
        {
            float length = (Horns.Length - 1) * Dz + 0.8f, wave = (Horns.Length - 1) * Step + 0.1f;
            var ps = Particle(parent, name, mat, lifetime: 1f, size: 1f, color: Color.white);
            ps.transform.localPosition = new Vector3(0f, 0.05f, Z0 + (Horns.Length - 1) * Dz * 0.5f);
            ps.transform.localRotation = Quaternion.Euler(0f, 90f, 0f);                       // edge x axis runs along z
            var main = ps.main;
            main.duration = Life;
            main.maxParticles = 40;
            var em = ps.emission;
            int cycles = isDust ? 16 : 10;
            em.SetBursts(new[] { new ParticleSystem.Burst(0f, 1, (short)(isDust ? 2 : 1), cycles, wave / cycles) });
            var shape = ps.shape;
            shape.enabled = true;
            shape.shapeType = ParticleSystemShapeType.SingleSidedEdge;
            shape.radius = length * 0.5f;
            shape.radiusMode = ParticleSystemShapeMultiModeValue.Random;   // random along the line; the bursts follow the wave in time
            var r = ps.GetComponent<ParticleSystemRenderer>();
            if (isDust)
            {
                // soft brown-grey dust puffs rising a little and spreading
                main.startLifetime = new ParticleSystem.MinMaxCurve(0.7f, 1.0f);
                main.startSpeed = new ParticleSystem.MinMaxCurve(0.2f, 0.6f);
                main.startSize = new ParticleSystem.MinMaxCurve(0.9f, 1.5f);
                main.startRotation = new ParticleSystem.MinMaxCurve(0f, 6.28f);
                main.startColor = new ParticleSystem.MinMaxGradient(new Color(0.56f, 0.48f, 0.4f, 0.7f), new Color(0.72f, 0.65f, 0.56f, 0.7f));
                var vel = ps.velocityOverLifetime; vel.enabled = true; vel.space = ParticleSystemSimulationSpace.World;
                vel.x = new ParticleSystem.MinMaxCurve(-0.6f, 0.6f); vel.z = new ParticleSystem.MinMaxCurve(0f); vel.y = new ParticleSystem.MinMaxCurve(0.4f, 0.9f);
                var rot = ps.rotationOverLifetime; rot.enabled = true; rot.z = new ParticleSystem.MinMaxCurve(-0.4f, 0.4f);
                SizeOverLifetime(ps, 0f, 0.6f, 1f, 1.4f);
                AlphaOverLifetime(ps, 0f, 0f, 0.15f, 0.7f, 0.6f, 0.4f, 1f, 0f);
                r.sortingOrder = -2;
            }
            else
            {
                // rock chunks thrown sideways, away from the fissure, heavy
                main.startLifetime = new ParticleSystem.MinMaxCurve(0.5f, 0.8f);
                main.startSpeed = 0f;
                main.startSize = new ParticleSystem.MinMaxCurve(0.28f, 0.55f);
                main.gravityModifier = 3.2f;
                main.startRotation3D = true;
                main.startRotationX = new ParticleSystem.MinMaxCurve(0f, 6.28f);
                main.startRotationY = new ParticleSystem.MinMaxCurve(0f, 6.28f);
                main.startRotationZ = new ParticleSystem.MinMaxCurve(0f, 6.28f);
                var vel = ps.velocityOverLifetime; vel.enabled = true; vel.space = ParticleSystemSimulationSpace.World;
                vel.x = new ParticleSystem.MinMaxCurve(-3.5f, 3.5f); vel.z = new ParticleSystem.MinMaxCurve(-0.5f, 1f); vel.y = new ParticleSystem.MinMaxCurve(2f, 4.5f);
                SizeOverLifetime(ps, 0f, 1f, 0.7f, 1f, 1f, 0f);
                r.renderMode = ParticleSystemRenderMode.Mesh;
                r.alignment = ParticleSystemRenderSpace.World;
                r.SetMeshes(new[] { Load("SM_VFX_Debris_Crystal_01"), Load("SM_VFX_Small_Crystal_03") });
                r.sortingOrder = 1;
            }
        }
    }
}
#endif
